(7125474, 1089130, 114225, '<td valign="top">Nice job getting up early to encounter this beauty, and share it with us.</td>', 'Nice job getting up early to encounter this beauty, and share it with us.', '2013-11-04 13:07:40.000000', NULL, 1),
(7125475, 1088783, 114225, '<td valign="top">Wow, way to put things in perspective!</td>', 'Wow, way to put things in perspective!', '2013-11-04 13:08:34.000000', NULL, 1),
(7125476, 1089488, 114225, '<td valign="top">Very nice use of complimentary colors.</td>', 'Very nice use of complimentary colors.', '2013-11-04 13:08:53.000000', NULL, 1),
(7125478, 1088432, 114225, '<td valign="top">Nice job lighting this side of the lighthouse to provide a beautiful view.<br/> <br/>Altough, it looks like there might be some spill over from the dodge brush onto the clouds surrounding the lighthouse.</td>', 'Nice job lighting this side of the lighthouse to provide a beautiful view. Altough, it looks like there might be some spill over from the dodge brush onto the clouds surrounding the lighthouse.', '2013-11-04 13:09:48.000000', NULL, 1),
