(7125763, 1088783, 114233, '<td valign="top">If this is isn''t a winner, it should be right up there. Great shot</td>', 'If this is isn''t a winner, it should be right up there. Great shot', '2013-11-05 08:29:46.000000', NULL, 1),
(7125939, 1089751, 170018, '<td valign="top">It looks like it''s going in the sky...</td>', 'It looks like it''s going in the sky...', '2013-11-05 23:45:25.000000', NULL, 1),
(7125945, 1089739, 170018, '<td valign="top">I''m afraid the sky looks too dramatic to just loose yourself. :-)</td>', 'I''m afraid the sky looks too dramatic to just loose yourself. :-)', '2013-11-05 23:46:58.000000', NULL, 1),
(7125949, 1089534, 170018, '<td valign="top">It a gorgeous view! Wish it did not have the black border...</td>', 'It a gorgeous view! Wish it did not have the black border...', '2013-11-05 23:48:22.000000', NULL, 1),
(7125950, 1089261, 170018, '<td valign="top">Awesome sky! Love it.</td>', 'Awesome sky! Love it.', '2013-11-05 23:49:18.000000', NULL, 1),
(7125951, 1088870, 22459, '<td valign="top">Another great fly shot. This would have done really well in the bug challenge :)</td>', 'Another great fly shot. This would have done really well in the bug challenge :)', '2013-11-05 23:49:19.000000', NULL, 1),
(7125952, 1089308, 170018, '<td valign="top">I''m jealous to people who can see and capture this! Reminds me of Harry Potter though, sorry. :-)</td>', 'I''m jealous to people who can see and capture this! Reminds me of Harry Potter though, sorry. :-)', '2013-11-05 23:51:52.000000', NULL, 1),
(7126087, 1089854, 43565, '<td valign="top">This seems to be an adorable baby, yet the focus is on her bow.</td>', 'This seems to be an adorable baby, yet the focus is on her bow.', '2013-11-06 09:29:17.000000', NULL, 1),
(7126090, 1088359, 43565, '<td valign="top">Pretty color in the sky. I find the tilted horizon line distracting.</td>', 'Pretty color in the sky. I find the tilted horizon line distracting.', '2013-11-06 09:43:23.000000', NULL, 1),
(7126093, 1087541, 43565, '<td valign="top">Wow! He would stand out in a crowd! Good lighting and details.</td>', 'Wow! He would stand out in a crowd! Good lighting and details.', '2013-11-06 09:51:39.000000', NULL, 1),
(7126250, 1086928, 100831, '<td valign="top">I feel the love.</td>', 'I feel the love.', '2013-11-06 18:18:56.000000', NULL, 1),
(7126252, 1089793, 60047, '<td valign="top">Nice capture! A bit too grainy and contrasty for my taste - but I recognize this may be the look you are going after.</td>', 'Nice capture! A bit too grainy and contrasty for my taste - but I recognize this may be the look you are going after.', '2013-11-06 18:55:55.000000', NULL, 1),
(7126253, 1089711, 60047, '<td valign="top">Love the dark path  with the gate. The foliage seems slightly heavily warm-toned and saturated.</td>', 'Love the dark path  with the gate. The foliage seems slightly heavily warm-toned and saturated.', '2013-11-06 18:57:37.000000', NULL, 1),
(7126254, 1088820, 60047, '<td valign="top">I had to stare at this for a bit to see that it is a section of masonry. I like the mottled colors on the stone. I think a different title could have served you even better.</td>', 'I had to stare at this for a bit to see that it is a section of masonry. I like the mottled colors on the stone. I think a different title could have served you even better.', '2013-11-06 18:59:08.000000', NULL, 1),
(7126256, 1087107, 60047, '<td valign="top">I really like the heavier contrast of this B&amp;W. I really like the way the mist fades everything out in the upper right corner. Interesting how both models are not looking at each other.</td>', 'I really like the heavier contrast of this B&W. I really like the way the mist fades everything out in the upper right corner. Interesting how both models are not looking at each other.', '2013-11-06 19:01:53.000000', NULL, 1),
(7126257, 1089227, 60047, '<td valign="top">Interesting use of the sun to create a semi-silhouette effect.</td>', 'Interesting use of the sun to create a semi-silhouette effect.', '2013-11-06 19:03:05.000000', NULL, 1),
(7126258, 1088783, 60047, '<td valign="top">This is a good shot w/out the person. But it is made much more interesting with the addition of the person. Nice management of the harsh light. Good job!</td>', 'This is a good shot w/out the person. But it is made much more interesting with the addition of the person. Nice management of the harsh light. Good job!', '2013-11-06 19:04:27.000000', NULL, 1),
(7126260, 1087583, 60047, '<td valign="top">Great abstract. I wish the dominant tree trunks were not so close to the center. This image has a great quality of causing me to want to look at it some more.</td>', 'Great abstract. I wish the dominant tree trunks were not so close to the center. This image has a great quality of causing me to want to look at it some more.', '2013-11-06 19:06:50.000000', NULL, 1),
(7126261, 1089647, 60047, '<td valign="top">Great composition. Whites slightly blown in the horse''s cheek. Love the contrast of the dark BG.</td>', 'Great composition. Whites slightly blown in the horse''s cheek. Love the contrast of the dark BG.', '2013-11-06 19:08:01.000000', NULL, 1),
(7126262, 1086392, 60047, '<td valign="top">A classic Fall scene done well.</td>', 'A classic Fall scene done well.', '2013-11-06 19:08:37.000000', NULL, 1),
(7126263, 1087845, 60047, '<td valign="top">I really like the effects the lights have on this shot.</td>', 'I really like the effects the lights have on this shot.', '2013-11-06 19:09:25.000000', NULL, 1),
(7126264, 1088595, 60047, '<td valign="top">Interesting crop choice. The long exposure and composition has me wondering if the primary subject is the ethereal water over the beach - or the bridge.</td>', 'Interesting crop choice. The long exposure and composition has me wondering if the primary subject is the ethereal water over the beach - or the bridge.', '2013-11-06 19:11:18.000000', NULL, 1),
(7126265, 1089457, 60047, '<td valign="top">Great capture of the subject. The shot would have been infinitely better if you had hung a black sheet in front of the couch and wall.I think some USM may have helped make the texture of the cat''s fur pop more.</td>', 'Great capture of the subject. The shot would have been infinitely better if you had hung a black sheet in front of the couch and wall.I think some USM may have helped make the texture of the cat''s fur pop more.', '2013-11-06 19:13:35.000000', NULL, 1),
(7126266, 1089816, 60047, '<td valign="top">Nice and crisp. Good to see the whites aren''t blown out by the harsh light. Love the fact that you captured the tongue so well.</td>', 'Nice and crisp. Good to see the whites aren''t blown out by the harsh light. Love the fact that you captured the tongue so well.', '2013-11-06 19:15:10.000000', NULL, 1),
(7126267, 1088592, 60047, '<td valign="top">Great composition. I think the reds and oranges are a bit too over-saturated for my taste. I really like the reeds in the FG.</td>', 'Great composition. I think the reds and oranges are a bit too over-saturated for my taste. I really like the reeds in the FG.', '2013-11-06 19:16:28.000000', NULL, 1),
(7126268, 1088014, 60047, '<td valign="top">I really like the quiet stillness that comes out of this shot. It seems just a bit too blue overall - but I love the way the yellows and the lichen pop against the blues.</td>', 'I really like the quiet stillness that comes out of this shot. It seems just a bit too blue overall - but I love the way the yellows and the lichen pop against the blues.', '2013-11-06 19:17:59.000000', NULL, 1),
(7126269, 1088677, 60047, '<td valign="top">A nice scene. I think the dead trees on the left detract from the shot. I also think you could have benefited from either adding some USM - or perhaps closed the aperture a bit more to bring the trees on the far side of the river into crisper focus.</td>', 'A nice scene. I think the dead trees on the left detract from the shot. I also think you could have benefited from either adding some USM - or perhaps closed the aperture a bit more to bring the trees on the far side of the river into crisper focus.', '2013-11-06 19:21:08.000000', NULL, 1),
(7126271, 1089048, 60047, '<td valign="top">The star of this shot is the fact the the leaves on the ground are visible despite the back-lighting from the sun. Cool place.</td>', 'The star of this shot is the fact the the leaves on the ground are visible despite the back-lighting from the sun. Cool place.', '2013-11-06 19:25:38.000000', NULL, 1),
(7126272, 1088359, 60047, '<td valign="top">Great sunset colors. Is it an optical illusion or is the horizon not straight?</td>', 'Great sunset colors. Is it an optical illusion or is the horizon not straight?', '2013-11-06 19:27:19.000000', NULL, 1),
(7126275, 1089616, 60047, '<td valign="top">I know you want to get the arbor in this, but I think the two subjects should be a lot closer and not so centered. Maybe if you cheated them forward and reduced your aperture you could get them to be a bigger part of the shot and yet still have the arbor?Nice locale.</td>', 'I know you want to get the arbor in this, but I think the two subjects should be a lot closer and not so centered. Maybe if you cheated them forward and reduced your aperture you could get them to be a bigger part of the shot and yet still have the arbor?Nice locale.', '2013-11-06 19:34:18.000000', NULL, 1),
(7126276, 1089705, 60047, '<td valign="top">I like the unusual color palette in this shot. I love the bokeh.</td>', 'I like the unusual color palette in this shot. I love the bokeh.', '2013-11-06 19:35:52.000000', NULL, 1),
(7126277, 1089662, 60047, '<td valign="top">Love the Fall colors. I wish it weren''t hazy in the BG.</td>', 'Love the Fall colors. I wish it weren''t hazy in the BG.', '2013-11-06 19:36:41.000000', NULL, 1),
(7126278, 1089818, 60047, '<td valign="top">Nice a crisp - but I''m not comfortable with the angle of the shot since this skews the lines of the window from the edges of the photo.</td>', 'Nice a crisp - but I''m not comfortable with the angle of the shot since this skews the lines of the window from the edges of the photo.', '2013-11-06 19:40:42.000000', NULL, 1),
(7126279, 1089841, 60047, '<td valign="top">Nice composition. I might have tried dodging the foreground just a bit due to its heavy darkness.Nice rich, deep blue sky.</td>', 'Nice composition. I might have tried dodging the foreground just a bit due to its heavy darkness.Nice rich, deep blue sky.', '2013-11-06 19:41:54.000000', NULL, 1),
(7126281, 1089850, 60047, '<td valign="top">I love the texture of the animal''s facial fur.</td>', 'I love the texture of the animal''s facial fur.', '2013-11-06 19:43:09.000000', NULL, 1),
(7126282, 1089512, 60047, '<td valign="top">great capture. Love his expression. Great crop choice. Nice management of your DOF.</td>', 'great capture. Love his expression. Great crop choice. Nice management of your DOF.', '2013-11-06 19:43:54.000000', NULL, 1),
(7126283, 1089570, 60047, '<td valign="top">Nice textures in this shot. Nice DOF management.</td>', 'Nice textures in this shot. Nice DOF management.', '2013-11-06 19:44:36.000000', NULL, 1),
(7126285, 1089482, 60047, '<td valign="top">Interesting title choice. I''m not so sure the foreground branch being out of focus helps this shot. I love the textures on the leaves that are in focus. Nice BG bokeh.</td>', 'Interesting title choice. I''m not so sure the foreground branch being out of focus helps this shot. I love the textures on the leaves that are in focus. Nice BG bokeh.', '2013-11-06 19:47:30.000000', NULL, 1),
(7126286, 1089738, 60047, '<td valign="top">Interestingly composed shot. I''d prefer just a hair less saturation on the oranges, though.</td>', 'Interestingly composed shot. I''d prefer just a hair less saturation on the oranges, though.', '2013-11-06 19:48:56.000000', NULL, 1),
(7126287, 1089724, 60047, '<td valign="top">I like the differing textures of the grasses in the foreground vs the structures and the trees and the clouds. I might have tried to offset the barn &amp; silo off center just a bit more.</td>', 'I like the differing textures of the grasses in the foreground vs the structures and the trees and the clouds. I might have tried to offset the barn & silo off center just a bit more.', '2013-11-06 19:50:43.000000', NULL, 1),
(7126288, 1089243, 60047, '<td valign="top">A classic subject. A classic shot. Nicely composed. Nice management of your DOF. Overall, done very well.</td>', 'A classic subject. A classic shot. Nicely composed. Nice management of your DOF. Overall, done very well.', '2013-11-06 19:51:56.000000', NULL, 1),
(7126289, 1089569, 60047, '<td valign="top">I''m not so sure you need that extra space to the right and to the left of the subject. I like her pose.</td>', 'I''m not so sure you need that extra space to the right and to the left of the subject. I like her pose.', '2013-11-06 19:53:47.000000', NULL, 1),
(7126290, 1089172, 60047, '<td valign="top">The high contrasty highlights really help this image work. There''s a nice symmetry between the frog''s texture and the surrounding textures.</td>', 'The high contrasty highlights really help this image work. There''s a nice symmetry between the frog''s texture and the surrounding textures.', '2013-11-06 19:56:07.000000', NULL, 1),
(7126291, 1089467, 60047, '<td valign="top">I like the silhouette aspect of this shot. I think the out of focus branches in the foreground really hurt.</td>', 'I like the silhouette aspect of this shot. I think the out of focus branches in the foreground really hurt.', '2013-11-06 19:58:25.000000', NULL, 1),
(7126292, 1089845, 60047, '<td valign="top">Interesting title - thought provoking. You''ve managed this rather harsh light pretty well. I love the yellows of the aspens contrasted against the blues and greens. Nice natural framing.</td>', 'Interesting title - thought provoking. You''ve managed this rather harsh light pretty well. I love the yellows of the aspens contrasted against the blues and greens. Nice natural framing.', '2013-11-06 20:00:27.000000', NULL, 1),
(7126293, 1086928, 60047, '<td valign="top">Love the expression on the child''s face. This shot would have been really quite  powerful without the adult and if it were cropped in just a bit closer. I like the choice of B&amp;W.</td>', 'Love the expression on the child''s face. This shot would have been really quite  powerful without the adult and if it were cropped in just a bit closer. I like the choice of B&W.', '2013-11-06 20:02:03.000000', NULL, 1),
