(7126295, 1089624, 60047, '<td valign="top">I think this shot is interesting. But the star of the show - and the one worthy of a portrait all by himself is the man on the left. Love his clothing ensemble, pose and expression in this B&amp;W!</td>', 'I think this shot is interesting. But the star of the show - and the one worthy of a portrait all by himself is the man on the left. Love his clothing ensemble, pose and expression in this B&W!', '2013-11-06 20:06:05.000000', NULL, 1),
(7126297, 1086562, 60047, '<td valign="top">It''s great that you got the subject frozen so well in the light. Looks like it might be just a bit blown on the highlights. I''d be tempted to crop this shot a bit more.</td>', 'It''s great that you got the subject frozen so well in the light. Looks like it might be just a bit blown on the highlights. I''d be tempted to crop this shot a bit more.', '2013-11-06 20:07:54.000000', NULL, 1),
