(7126302, 1088405, 60047, '<td valign="top">Focus spot on the eyes - nice job. I would have like to see the rest of his body in the field of focus if that was a choice.</td>', 'Focus spot on the eyes - nice job. I would have like to see the rest of his body in the field of focus if that was a choice.', '2013-11-06 20:17:28.000000', NULL, 1),
(7126303, 1089496, 60047, '<td valign="top">A great shot of this iconic subject. Impressed with the capture of the stillness. I love the rich blues of the water.</td>', 'A great shot of this iconic subject. Impressed with the capture of the stillness. I love the rich blues of the water.', '2013-11-06 20:18:26.000000', NULL, 1),
(7126304, 1087774, 60047, '<td valign="top">This is a very clever capture. It translates what must be impressive to a stereoscopic being into a flat image very well. You really get the sense of strong depth perception with this shot. The B&amp;W choice really assists.</td>', 'This is a very clever capture. It translates what must be impressive to a stereoscopic being into a flat image very well. You really get the sense of strong depth perception with this shot. The B&W choice really assists.', '2013-11-06 20:20:17.000000', NULL, 1),
(7126305, 1086443, 60047, '<td valign="top">The grain and monochrome helps take this snapshot-style photo and transform it into a photo worth contemplating. Good work.</td>', 'The grain and monochrome helps take this snapshot-style photo and transform it into a photo worth contemplating. Good work.', '2013-11-06 20:21:43.000000', NULL, 1),
