(7126487, 1089816, 65234, '<td valign="top">Very cool tongue he''s got there ;-)  Great detail on this bird.</td>', 'Very cool tongue he''s got there ;-)  Great detail on this bird.', '2013-11-07 08:19:57.000000', NULL, 1),
(7126488, 1089694, 65234, '<td valign="top">Great capture!</td>', 'Great capture!', '2013-11-07 08:20:23.000000', NULL, 1),
(7126490, 1089494, 108580, '<td valign="top">The inclusion of the "dark bird" makes this work very well. The Vignetting is a bit OTT as it has also darkened the bottom corners of the building which looks odd. Still a 7.</td>', 'The inclusion of the "dark bird" makes this work very well. The Vignetting is a bit OTT as it has also darkened the bottom corners of the building which looks odd. Still a 7.', '2013-11-07 08:32:39.000000', NULL, 1),
(7126497, 1089451, 100831, '<td valign="top">Billiant.</td>', 'Billiant.', '2013-11-07 08:52:18.000000', NULL, 1),
(7126502, 1089791, 60047, '<td valign="top">An interesting story being told with this photo.</td>', 'An interesting story being told with this photo.', '2013-11-07 09:06:31.000000', NULL, 1),
(7126503, 1088750, 60047, '<td valign="top">Great juxtaposition of the Red and Black against the lovely atypical bokeh of the BG.</td>', 'Great juxtaposition of the Red and Black against the lovely atypical bokeh of the BG.', '2013-11-07 09:07:28.000000', NULL, 1),
(7126504, 1089843, 60047, '<td valign="top">Wonderfully idyllic and ethereal.</td>', 'Wonderfully idyllic and ethereal.', '2013-11-07 09:07:52.000000', NULL, 1),
(7126506, 1089784, 60047, '<td valign="top">An iconic subject and image. Good job capturing this with the soft light of the end of the day.</td>', 'An iconic subject and image. Good job capturing this with the soft light of the end of the day.', '2013-11-07 09:08:58.000000', NULL, 1),
(7126507, 1089543, 60047, '<td valign="top">An interesting dark dominated B&amp;W. Great focus on the eye.</td>', 'An interesting dark dominated B&W. Great focus on the eye.', '2013-11-07 09:09:36.000000', NULL, 1),
(7126508, 1089187, 60047, '<td valign="top">Brings back memories of a trip taken 30 years ago and camping outside the city of Innsbruck. A great idyllic image.</td>', 'Brings back memories of a trip taken 30 years ago and camping outside the city of Innsbruck. A great idyllic image.', '2013-11-07 09:11:10.000000', NULL, 1),
(7126509, 1088241, 60047, '<td valign="top">I like the bulbous shapes and textures of the tree''s trunk.</td>', 'I like the bulbous shapes and textures of the tree''s trunk.', '2013-11-07 09:11:47.000000', NULL, 1),
(7126510, 1089739, 60047, '<td valign="top">Interesting how water falls are always so captivating to look at.</td>', 'Interesting how water falls are always so captivating to look at.', '2013-11-07 09:12:33.000000', NULL, 1),
(7126511, 1089550, 60047, '<td valign="top">A great image capturing this guy at work. Great focus and the black BG really helps.</td>', 'A great image capturing this guy at work. Great focus and the black BG really helps.', '2013-11-07 09:13:34.000000', NULL, 1),
(7126512, 1087784, 60047, '<td valign="top">Great composition. Great color palette.</td>', 'Great composition. Great color palette.', '2013-11-07 09:14:13.000000', NULL, 1),
(7126513, 1089811, 60047, '<td valign="top">What a fun and quirky image!</td>', 'What a fun and quirky image!', '2013-11-07 09:14:32.000000', NULL, 1),
(7126514, 1089451, 60047, '<td valign="top">This is quite an interesting image. The centered subject, usually a poor composition choice, works really well with the longer exposure, here.</td>', 'This is quite an interesting image. The centered subject, usually a poor composition choice, works really well with the longer exposure, here.', '2013-11-07 09:15:36.000000', NULL, 1),
(7126515, 1089639, 60047, '<td valign="top">I really love the lines and curves in this image. Great choice to go B&amp;W. T love the POV and the composition of this photo.</td>', 'I really love the lines and curves in this image. Great choice to go B&W. T love the POV and the composition of this photo.', '2013-11-07 09:16:28.000000', NULL, 1),
(7126516, 1089776, 60047, '<td valign="top">Interesting effect to have the sharp focus on the globe and soft focus in the FG &amp; BG.</td>', 'Interesting effect to have the sharp focus on the globe and soft focus in the FG & BG.', '2013-11-07 09:17:25.000000', NULL, 1),
(7126517, 1089827, 60047, '<td valign="top">I really like this abstract. I usually don''t care for them bu the color palette and tones and patterns are quite pleasing to the eye. Great work.</td>', 'I really like this abstract. I usually don''t care for them bu the color palette and tones and patterns are quite pleasing to the eye. Great work.', '2013-11-07 09:18:30.000000', NULL, 1),
(7126518, 1089015, 60047, '<td valign="top">What a magnificent creature.</td>', 'What a magnificent creature.', '2013-11-07 09:18:52.000000', NULL, 1),
(7126519, 1089685, 60047, '<td valign="top">I really like the composition, crop choice and pose. Interesting blue tones on the black hair complimenting the magenta BG. If I wanted to be picky, I''d suggest matching the color of the lipstick more closely to the BG color. I would also suggest the light on her face is just a bit too bright. Great work on this one.</td>', 'I really like the composition, crop choice and pose. Interesting blue tones on the black hair complimenting the magenta BG. If I wanted to be picky, I''d suggest matching the color of the lipstick more closely to the BG color. I would also suggest the light on her face is just a bit too bright. Great work on this one.', '2013-11-07 09:21:42.000000', NULL, 1),
(7126520, 1089719, 60047, '<td valign="top">A nice shot of a common city sight. You''ve brought out the beauty of something most of us see as mundane. Nice work.</td>', 'A nice shot of a common city sight. You''ve brought out the beauty of something most of us see as mundane. Nice work.', '2013-11-07 09:22:50.000000', NULL, 1),
(7126521, 1086988, 60047, '<td valign="top">I really like this. Evocative of a Lord of The Rings Hobbit world.</td>', 'I really like this. Evocative of a Lord of The Rings Hobbit world.', '2013-11-07 09:23:40.000000', NULL, 1),
(7126522, 1088286, 60047, '<td valign="top">Nice work with such harsh light. Great crop decision.</td>', 'Nice work with such harsh light. Great crop decision.', '2013-11-07 09:24:16.000000', NULL, 1),
(7126523, 1089515, 60047, '<td valign="top">I really like the cool blues of the sky contrasted with the golds in the trees. Having the birds in flight really takes this image out of the snapshot category and into the photograph category.</td>', 'I really like the cool blues of the sky contrasted with the golds in the trees. Having the birds in flight really takes this image out of the snapshot category and into the photograph category.', '2013-11-07 09:25:49.000000', NULL, 1),
(7126524, 1089660, 60047, '<td valign="top">Quite a thought-provoking photo. The negative space really works well with her pose.</td>', 'Quite a thought-provoking photo. The negative space really works well with her pose.', '2013-11-07 09:26:36.000000', NULL, 1),
(7126525, 1089471, 60047, '<td valign="top">Making a mist-on-the-lake photo is hard because it tends to be much more stunning in stereoscopic vision than in the world of the flat photograph. But the clarity of the fall leaves really helps make the fog work in this shot.</td>', 'Making a mist-on-the-lake photo is hard because it tends to be much more stunning in stereoscopic vision than in the world of the flat photograph. But the clarity of the fall leaves really helps make the fog work in this shot.', '2013-11-07 09:28:11.000000', NULL, 1),
(7126526, 1089629, 60047, '<td valign="top">I like the visual irony of this shot. Good work!</td>', 'I like the visual irony of this shot. Good work!', '2013-11-07 09:28:35.000000', NULL, 1),
(7126527, 1089530, 60047, '<td valign="top">A classic pose and composition. Great BG.</td>', 'A classic pose and composition. Great BG.', '2013-11-07 09:29:21.000000', NULL, 1),
(7126528, 1089721, 60047, '<td valign="top">What an interesting effect to have the yellow cast to this shot. Kinda takes you back into the past.</td>', 'What an interesting effect to have the yellow cast to this shot. Kinda takes you back into the past.', '2013-11-07 09:30:04.000000', NULL, 1),
(7126529, 1089697, 60047, '<td valign="top">Nice and crisp. Interesting choice to include the vignette in the top corners. I enjoy the cool-toned color cast.</td>', 'Nice and crisp. Interesting choice to include the vignette in the top corners. I enjoy the cool-toned color cast.', '2013-11-07 09:31:14.000000', NULL, 1),
(7126530, 1089261, 60047, '<td valign="top">I love the detail of the clouds in this shot.</td>', 'I love the detail of the clouds in this shot.', '2013-11-07 09:31:52.000000', NULL, 1),
(7126531, 1087703, 60047, '<td valign="top">The clouds on the horizon are the stars of this shot. Very dramatic and captivating.</td>', 'The clouds on the horizon are the stars of this shot. Very dramatic and captivating.', '2013-11-07 09:32:45.000000', NULL, 1),
(7126532, 1087849, 60047, '<td valign="top">Wonderful composition. Great complimentary colors. Nice textures in the sand.</td>', 'Wonderful composition. Great complimentary colors. Nice textures in the sand.', '2013-11-07 09:33:25.000000', NULL, 1),
(7126533, 1089854, 60047, '<td valign="top">Interesting use of very limited focus. I would think the child''s parents would love this shot.</td>', 'Interesting use of very limited focus. I would think the child''s parents would love this shot.', '2013-11-07 09:34:18.000000', NULL, 1),
(7126534, 1089330, 60047, '<td valign="top">Wow, the golf course sign really changes this photo in that it brings man kind into the mix and juxtaposes it against nature.</td>', 'Wow, the golf course sign really changes this photo in that it brings man kind into the mix and juxtaposes it against nature.', '2013-11-07 09:36:01.000000', NULL, 1),
(7126535, 1089720, 60047, '<td valign="top">I really like the subject and the concept of a high contrast B&amp;W given his skin texture. It''s interesting to see the almost metallic nature of the highlights. Great use of light in this shot.</td>', 'I really like the subject and the concept of a high contrast B&W given his skin texture. It''s interesting to see the almost metallic nature of the highlights. Great use of light in this shot.', '2013-11-07 09:37:32.000000', NULL, 1),
(7126536, 1089828, 60047, '<td valign="top">An interesting high contrast B&amp;W.</td>', 'An interesting high contrast B&W.', '2013-11-07 09:38:00.000000', NULL, 1),
(7126537, 1089465, 123089, '<td valign="top">Look like a winner to me ;)<br/>Amazing</td>', 'Look like a winner to me ;)Amazing', '2013-11-07 09:40:12.000000', NULL, 1),
(7126538, 1087703, 68178, '<td valign="top">Holy cow, great clouds!</td>', 'Holy cow, great clouds!', '2013-11-07 10:01:07.000000', NULL, 1),
(7126557, 1089452, 30669, '<td valign="top">Looks like a beautiful spot.</td>', 'Looks like a beautiful spot.', '2013-11-07 10:59:27.000000', NULL, 1),
