(7126603, 1086443, 100831, '<td valign="top">it''s amazing you can get all that good stuff for a hundred cents.</td>', 'it''s amazing you can get all that good stuff for a hundred cents.', '2013-11-07 12:50:19.000000', NULL, 1),
