(7126613, 1087583, 11769, '<td valign="top">interesting effect.</td>', 'interesting effect.', '2013-11-07 13:04:16.000000', NULL, 1),
(7126617, 1088355, 11769, '<td valign="top">this is a beautiful image</td>', 'this is a beautiful image', '2013-11-07 13:09:51.000000', NULL, 1),
(7126620, 1088783, 138630, '<td valign="top">My pick for the blue - I think it''s perfectly lovely and that lone figure in the blue jacket that matches the bit of sky takes it over the top.  Wow, what a location.  Already voted, back to comment.</td>', 'My pick for the blue - I think it''s perfectly lovely and that lone figure in the blue jacket that matches the bit of sky takes it over the top.  Wow, what a location.  Already voted, back to comment.', '2013-11-07 13:14:48.000000', NULL, 1),
(7126622, 1089488, 138630, '<td valign="top">Simple and actually ordinary in terms of subject - but the pop of the color (I adore blue and yellow) and the clarity and selective focus are all perfect.  Top 10% for me.  Already voted, back to comment.</td>', 'Simple and actually ordinary in terms of subject - but the pop of the color (I adore blue and yellow) and the clarity and selective focus are all perfect.  Top 10% for me.  Already voted, back to comment.', '2013-11-07 13:17:37.000000', NULL, 1),
(7126623, 1087703, 138630, '<td valign="top">What a great sky - those dense, low-lying clouds are something.  It''s a bit dark for me but that may be my monitor.  Top 10% for me.  Already voted, back to comment.</td>', 'What a great sky - those dense, low-lying clouds are something.  It''s a bit dark for me but that may be my monitor.  Top 10% for me.  Already voted, back to comment.', '2013-11-07 13:18:35.000000', NULL, 1),
(7126624, 1089624, 138630, '<td valign="top">I adore this one.  I have it at 7 right now (my top group - I''m in the process of bumping and this will definitely go up).  I wish for something different where the hands and woman''s head meet - a little separation, maybe? - and in the amount of space at the top - too much above the picture BUT you sure don''t want to cut the statue''s head any more.  That said, this is obviously not one of those situations where you could move around unobtrusively and look for the slightly different angle.  And the expressions and postures of the man and woman, laid in against that wonderful piece of art as they are and in combination with the stylized statue - well, they are priceless.  I really hope you are the kind of person who likes to play around with things later.  I would for sure get rid of the name tags (though they fit the story, they are imo more distracting than helpful) and I really think it would be quite possible to move the statue back and shorten it a bit.<br/>Top 10% for me.  Already voted and commented; back to bump.<br/> <br/>Reading other comments after roll-over.  I thought of strangling, too - but the angle isn''t quite right for me for that.  Maybe it could be, though :) <br/><br/><i>Message edited by author 2013-11-08 00:12:18.</i></td>', 'I adore this one.  I have it at 7 right now (my top group - I''m in the process of bumping and this will definitely go up).  I wish for something different where the hands and woman''s head meet - a little separation, maybe? - and in the amount of space at the top - too much above the picture BUT you sure don''t want to cut the statue''s head any more.  That said, this is obviously not one of those situations where you could move around unobtrusively and look for the slightly different angle.  And the expressions and postures of the man and woman, laid in against that wonderful piece of art as they are and in combination with the stylized statue - well, they are priceless.  I really hope you are the kind of person who likes to play around with things later.  I would for sure get rid of the name tags (though they fit the story, they are imo more distracting than helpful) and I really think it would be quite possible to move the statue back and shorten it a bit.Top 10% for me.  Already voted and commented; back to bump. Reading other comments after roll-over.  I thought of strangling, too - but the angle isn''t quite right for me for that.  Maybe it could be, though :) ', '2013-11-07 13:19:04.000000', '2013-11-08 00:12:18.000000', 1),
(7126625, 1087772, 138630, '<td valign="top">Great feeling here and I love the minimalist look here.  Great tones, too.  Top 10% for me.  Already voted, back to comment.</td>', 'Great feeling here and I love the minimalist look here.  Great tones, too.  Top 10% for me.  Already voted, back to comment.', '2013-11-07 13:19:53.000000', NULL, 1),
(7126626, 1089727, 138630, '<td valign="top">Terrific face and black and white is the perfect choice for this character, I think.  The processing is a bit too strong for me - I''m not fond of that super sharpened, silver toned look - but this is a good choice for the subject and I know most people love it.  Top 10% for me.  Already voted, back to comment.</td>', 'Terrific face and black and white is the perfect choice for this character, I think.  The processing is a bit too strong for me - I''m not fond of that super sharpened, silver toned look - but this is a good choice for the subject and I know most people love it.  Top 10% for me.  Already voted, back to comment.', '2013-11-07 13:23:00.000000', NULL, 1),
(7126628, 1089838, 108580, '<td valign="top">That''s just weird and cool all wrapped up in one.</td>', 'That''s just weird and cool all wrapped up in one.', '2013-11-07 13:30:07.000000', NULL, 1),
(7126629, 1088783, 108580, '<td valign="top">Nice entry for -ve Space. Not bad for a FS either. We are oh so small.</td>', 'Nice entry for -ve Space. Not bad for a FS either. We are oh so small.', '2013-11-07 13:30:46.000000', NULL, 1),
(7126631, 1089786, 108580, '<td valign="top">Lovely natural exposure with 3 distinct elements of fore, water and sky. Distant is perhaps a bit soft.</td>', 'Lovely natural exposure with 3 distinct elements of fore, water and sky. Distant is perhaps a bit soft.', '2013-11-07 13:34:41.000000', NULL, 1),
(7126632, 1089501, 108580, '<td valign="top">Pretty, well composed and exposed but the sharpness is not there :/</td>', 'Pretty, well composed and exposed but the sharpness is not there :/', '2013-11-07 13:35:15.000000', NULL, 1),
